import { prisma } from '@/lib/prisma';

export async function getAuthorWithRecentPosts(authorId: string) {
  return await prisma.user.findUnique({
    where: { id: authorId },
    select: {
      id: true,
      name: true,
      email: true,
      // Nested pagination and filtering on posts!
      posts: {
        where: { published: true },
        orderBy: { createdAt: 'desc' },
        take: 5,
        select: {
          id: true,
          title: true,
          createdAt: true
        }
      },
      _count: {
        select: { posts: true } // Returns total post count for pagination UI
      }
    }
  });
}
